def transform_v2(grid):
    n=len(grid)
    out=[row[:] for row in grid]
    # Uniform rows encode a repeated sequence of horizontal bands.
    row_values=[]
    row_mode=True
    for row in grid:
        vals=set(row)-{0}
        if len(vals)>1:
            row_mode=False; break
        row_values.append(next(iter(vals)) if vals else 0)
    if row_mode:
        known={i:v for i,v in enumerate(row_values) if v}
        p=next(p for p in range(1,n+1) if all(len({v for i,v in known.items() if i%p==q})<=1 for q in range(p)) and all(any(i%p==q for i in known) for q in range(p)))
        seq={q:next(v for i,v in known.items() if i%p==q) for q in range(p)}
        for r in range(n):
            if row_values[r]==0:
                out[r]=[seq[r%p]]*n
        return out
    for kind, keyfn in [('main',lambda r,c:(c-r)%n),('anti',lambda r,c:(r+c)%n)]:
        clues={}
        conflict=False
        for r in range(n):
            for c in range(n):
                v=grid[r][c]
                if v:
                    k=keyfn(r,c)
                    if k in clues and clues[k]!=v: conflict=True
                    clues[k]=v
        if conflict or not clues: continue
        periods=[]
        for p in range(1,n+1):
            ok=all(len({v for k,v in clues.items() if k%p==q})<=1 for q in range(p))
            complete=all(any(k%p==q for k in clues) for q in range(p))
            if ok and complete: periods.append(p)
        if periods:
            p=min(periods)
            seq={q:next(v for k,v in clues.items() if k%p==q) for q in range(p)}
            for r in range(n):
                for c in range(n):
                    if grid[r][c]==0: out[r][c]=seq[keyfn(r,c)%p]
            return out
    return out

